private getVersionMismatchReason(theirSchema: SerializedSchema) {
	const ourSchema = this.serializedSchema

	if (theirSchema.schemaVersion > ourSchema.schemaVersion) {
		return TLSyncErrorCloseEventReason.SERVER_TOO_OLD
